    code: "PROGRAM SPRING_MASS\n  ! Classic damped harmonic oscillator in ACSL\n  INITIAL\n    CONSTANT k = 4.0, c = 0.2, m = 1.0\n    CONSTANT x0 = 1.0, v0 = 0.0\n    INTEGER npts = 100\n    LOGICAL active = .TRUE.\n    ARRAY gains(3) = 1.0, 2.0, 3.0\n    TABLE ftab, 1, 3 / 0.0, 1.0, 2.0, 0.0, 1.0, 4.0 /\n    CINTERVAL cint = 0.05\n    MAXTERVAL maxt = 0.01\n    ALGORITHM ialg = 5\n  END\n\n  DYNAMIC\n    DERIVATIVE\n      DERIVT = a\n      a = (-k * x - c * v) / m\n      v = INTEG(a, v0)\n      x = INTEG(v, x0)\n      PROCEDURAL(energy = x, v)\n        energy = 0.5 * m * v**2 + 0.5 * k * x**2\n      END\n      SCHEDULE sample_ev .AT. 1.0\n    END\n\n    DISCRETE sample_ev\n      INTERVAL dt = 0.5\n      sampled_x = x\n    END\n\n    TERMT(t .GE. 5.0, 'Simulation complete')\n  END\n\n  TERMINAL\n    final_e = 0.5 * k * x**2\n  END\nEND",
