    id: "vhdl-example-2",
    title: "VHDL Example 2",
    category: "VHDL",
    lang: "vhdl",
    description: "VHDL (.vhd) starter model",
    code: 'library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n\npackage my_pkg is\n  constant WIDTH : integer := 4;\n  type state_t is (IDLE, RUN, DONE);\nend package my_pkg;\n\npackage body my_pkg is\n  constant INTERNAL_C : integer := 1;\nend package body my_pkg;\n\nentity demo_unit is\n  generic (\n    N : integer := 4\n  );\n  port (\n    clk   : in  std_logic;\n    rst   : in  std_logic;\n    sel   : in  std_logic_vector(1 downto 0);\n    a, b  : in  std_logic_vector(3 downto 0);\n    y     : out std_logic_vector(3 downto 0)\n  );\nend entity demo_unit;\n\narchitecture rtl of demo_unit is\n  signal mux_out : std_logic_vector(3 downto 0);\n  signal tmp_s   : std_logic;\n\n  component inv_gate is\n    port (\n      i : in  std_logic;\n      o : out std_logic\n    );\n  end component inv_gate;\nbegin\n  -- Conditional concurrent assignment (when ... else)\n  mux_out <= a when sel = "00" else b;\n\n  -- Selected concurrent assignment (with ... select)\n  with sel select\n    tmp_s <= \'0\' when "00",\n             \'1\' when others;\n\n  -- Component instantiation with port map\n  u_inv : inv_gate port map (i => rst, o => tmp_s);\n\n  -- Clocked process with variable, if/elsif/else, case, and for loop\n  p_main : process(clk, rst)\n    variable acc : std_logic_vector(3 downto 0);\n  begin\n    if rst = \'1\' then\n      y <= (others => \'0\');\n    elsif rising_edge(clk) then\n      acc := mux_out;\n      case sel is\n        when "00" =>\n          y <= acc;\n        when "01" | "10" =>\n          for k in 0 to 3 loop\n            y(k) <= acc(k);\n          end loop;\n        when others =>\n          null;\n      end case;\n    end if;\n  end process p_main;\nend architecture rtl;',
